#include "reign/bink_movie.hpp"
#include "reign/archive.hpp"
#include <iostream>
#include <fstream>
int main(int argc,char **argv){try{if(argc!=2&&argc!=3)throw std::runtime_error("Usage: bink_probe base.zwp");reign::Archive base(argv[1]);for(int i=0;i<3;++i){auto name="intro-movie-"+std::to_string(i)+".bik";reign::BinkMovie movie(base.read(name));std::size_t samples=0,frames=0;std::uint64_t checksum=0;for(double time=0;time<movie.duration();time+=1./60){if(!movie.advance(time))throw std::runtime_error("Movie ended early");auto pcm=movie.drain_audio();samples+=pcm.size()/2;for(auto p:pcm)checksum=checksum*33+std::uint16_t(p);if(argc==3&&frames==std::size_t(movie.duration()*30)){std::ofstream out(std::string(argv[2])+"-"+std::to_string(i)+".ppm",std::ios::binary);out<<"P6\n"<<movie.width()<<' '<<movie.height()<<"\n255\n";auto &pixels=movie.rgba();for(std::size_t p=0;p<pixels.size();p+=4)out.write(reinterpret_cast<const char*>(pixels.data()+p),3);if(!out)throw std::runtime_error("Frame write failed");}++frames;}if(movie.advance(movie.duration()))throw std::runtime_error("Movie failed to end");std::cout<<name<<" "<<movie.width()<<"x"<<movie.height()<<" duration="<<movie.duration()<<" sample-rate="<<movie.sample_rate()<<" stereo-samples="<<samples<<" display-frames="<<frames<<" audio-checksum="<<checksum<<'\n';}std::cout<<"Original Bink video/audio decode: PASS\n";}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
